  const background = { voltgrid: "linear-gradient(125deg,#143b2e,#0c4a3d)", bridgepay: "linear-gradient(125deg,#2c1e49,#55326e)", careloop: "linear-gradient(125deg,#592b3f,#8c4c59)", atlas: "linear-gradient(125deg,#202c50,#334b7c)", goodharvest: "linear-gradient(125deg,#34411c,#56672c)", rethread: "linear-gradient(125deg,#65421f,#a86d34)" }[startup.id];
